/**
 *
 * DataTableRowReorder provides a drag handle for reordering DataTable rows.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableRowReorder
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableRowReorderEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableRowReorderPassThroughType<E> = PassThroughType<DataTableRowReorderInstance, E>;
export interface DataTableRowReorderPassThrough {
    root?: DataTableRowReorderPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
export interface DataTableRowReorderProps extends BaseComponentProps<DataTableRowReorderInstance, unknown, DataTableRowReorderPassThrough, 'span'> {
    /**
     * Index of the row for reordering.
     */
    rowIndex: number;
}
export interface DataTableRowReorderState {
}
export interface DataTableRowReorderExposes {
    datatable: DataTableRootInstance | undefined | null;
}
export type DataTableRowReorderInstance = ComponentInstance<DataTableRowReorderProps, DataTableRowReorderState, DataTableRowReorderExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableRowReorderEvent`.
 */
export interface DataTableRowReorderEvent extends UseDataTableRowReorderEvent {
}
